#!/usr/bin/env bash
set -uo pipefail
# InLightBio CN Deploy - 2026-11-18 homepage news add:
# 14 deals/financing items + 2 domestic conferences.
# Overlay: index.html + content/weekly_deals.js
# (therasik-inlight merge commit 4e713f9719de679a92d35f6e1cc21d198467d11c, PR #121).
# Copies the live root to a NEW release dir; never deletes or edits the old root.
# Does not delete Aliyun 命令助手 commands, hidden wx-src pages, or the stale
# /www/wwwroot/inlightbio_cn_rel_20261118_427ed5e dir left by the earlier ivo v1 abort.
# Do not re-run deploy_cn_20261117_p03b.sh or the ivo downgrade v1/v2/v3 scripts.
# Writes rollback.sh in the new release dir (points back to the current live r2 root).
# Pipe-safe: the overlay bundle is a quoted heredoc (not read from $0 or BASH_SOURCE),
# so this script behaves the same when run as a file or piped to bash.
EXPECTED_SHA256="703ec00dffbd66500818e83f993101f88e0f75f5a655e043b298da08301090db"
PRE_PAGE_SHA="77b5b829e33d244517c45db5d09b354535cb870586f197510df01006208e0c08"
AFTER_PAGE_SHA="f360b32c5921731102bf856dad5101109a1d093d935d683d39a6177f4ecf4ae5"
PRE_WEEKLY_SHA="77b36a0025affeaafd0a90f3d1f156a0194c2faea7bd5e4fae68743fa616fb95"
AFTER_WEEKLY_SHA="8f9d585d7da376c9dc783d2713a52227ee1c32ee8b2a77a2170e4a2f6837f5c2"
ARTICLE_SHA="0335c6fb05eee1860362e23501948dc498613f8d05ef881be290034d4d353278"
VHOST_CONF="/www/server/panel/vhost/nginx/inlightbio.cn.conf"
EXPECTED_OLD_ROOT="/www/wwwroot/inlightbio_cn_rel_20261118_427ed5e_r2"
NEW_REL_DIR="/www/wwwroot/inlightbio_cn_rel_20261118_4e713f9_news"
LOG="/var/log/inlightbio_cn_deploy_20261118_news.log"
CURRENT_ROOT=""; BACKUP_CONF=""
summary() { echo "$1 NEW_ROOT=$NEW_REL_DIR OLD_ROOT=${CURRENT_ROOT:-?} VHOST_BACKUP=${BACKUP_CONF:-none} LOG=$LOG"; }
abort() { echo "ERR: $1" | tee -a "$LOG"; summary "FAIL_$2_NOCHANGE"; exit 1; }
restore() { echo "ERR: $1" | tee -a "$LOG"; cp -a "$BACKUP_CONF" "$VHOST_CONF"; nginx -t >>"$LOG" 2>&1 && nginx -s reload >>"$LOG" 2>&1; summary "FAIL_$2_RESTORED"; exit 1; }
if ! { : > "$LOG"; } 2>/dev/null; then LOG=/tmp/inlightbio_cn_deploy_20261118_news.log; : > "$LOG"; fi
case "$NEW_REL_DIR" in
  *MERGED_SHA*) abort "NEW_REL_DIR still has MERGED_SHA placeholder; finalize with the merged therasik-inlight SHA before running" PLACEHOLDER ;;
esac
TMPD=$(mktemp -d); trap 'rm -rf "$TMPD"' EXIT
# Decode the embedded bundle from this heredoc (works when the script is a file or stdin).
base64 -d > "$TMPD/o.tgz" <<'__BUNDLE_BASE64__' || abort "bundle base64 decode failed" B64
